import * as React from "react";
import axios from "axios";
import MainLayout from "../layouts/MainLayout";
import { GlobalProvider } from "../components/context/GlobalContext";
import { navigate } from "gatsby"



export default function TestCart() {
  const [cartIds, setCartIds] = React.useState([]);
  const [cartItems, setCartItems] = React.useState([]);
  const [addressIndex, setAddressIndex] = React.useState(0);
  const [addresses, setAddresses] = React.useState(() => {

    const saved =  typeof window !== "undefined" ? localStorage.getItem("saved_addresses") : null;

    return saved ? JSON.parse(saved) : [{}];
  });
  const [validStatus, setValidStatus] = React.useState("unknown");
  const [boxSize, setBoxSize] = React.useState("medium");
  const [shippingCost, setShippingCost] = React.useState(null);
    const [shippingMeta, setShippingMeta] = React.useState(null);
  const [shippingLoading, setShippingLoading] = React.useState(false);
  const [shippingLabelUrl, setShippingLabelUrl] = React.useState(null);
const [shippingNow, setShippingNow] = React.useState(false);
const [payingNow, setPayNow] = React.useState(false);
  const [checkoutUrl, setCheckoutUrl] = React.useState(null);


  const address = addresses[addressIndex] || {};

  const updateAddress = (field, value) => {
    const updated = [...addresses];
    updated[addressIndex] = { ...updated[addressIndex], [field]: value };
    setAddresses(updated);
    if(typeof window !== "undefined" )
      localStorage.setItem("saved_addresses", JSON.stringify(updated));
  };

  const handleNextAddress = () => {
    if (addressIndex < addresses.length - 1) setAddressIndex(addressIndex + 1);
  };

  const handlePrevAddress = () => {
    if (addressIndex > 0) setAddressIndex(addressIndex - 1);
  };
const handleShipNow = async () => {
  const weight = cartItems.reduce((acc, item) => acc + parseFloat(item.weight || 0), 0);
  const box = boxOptions[boxSize];

  const payload = {
    address: {
      streetLines: [address.line1 || ""],
      city: address.city || "",
      stateOrProvinceCode: address.state || "",
      postalCode: address.zip || "",
      countryCode: "US",
      residential: false
    },
    weight: {
      units: "LB",
      value: weight
    },
    dimensions: {
      length: box.length,
      width: box.width,
      height: box.height,
      units: "IN"
    },
    recipientName: "John Doe", // Replace with actual input later
    phone: address.phone || "5551234567"
  };

  setShippingNow(true);
  setShippingLabelUrl(null);

  try {
    const res = await fetch("https://fedex-msb.makethemcall.workers.dev/fedex-ship", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });

    const data = await res.json();

    const labelUrl = data?.labelUrl;
    const trackingNumber = data?.trackingNumber || data?.masterTrackingId?.trackingNumber || null;

    if (labelUrl) {
      setShippingLabelUrl(labelUrl);
      console.log("📦 Shipping Label URL:", labelUrl);
      console.log("🚚 Tracking Number:", trackingNumber);

      // Store tracking number if needed
      if (trackingNumber) {
            if(typeof window !== "undefined" )
        localStorage.setItem("last_tracking_number", trackingNumber);

        // Optional: Send to your backend for record-keeping
        // await fetch("/api/save-tracking", {
        //   method: "POST",
        //   headers: { "Content-Type": "application/json" },
        //   body: JSON.stringify({ trackingNumber, address, cart: cartItems }),
        // });
      }
    } else {
      console.error("No shipping label returned from FedEx API.");
    }

  } catch (err) {
    console.error("Shipping error:", err);
  } finally {
    setShippingNow(false);
  }
};

const handlePayNow = async () => {
  setPayNow(true);
  setCheckoutUrl(null);

  const cartPayload = cartItems.map((item) => ({
    id: item.id,
    quantity: 1,
  }));
  


   const shippingTrackingNumber =  typeof window !== "undefined" ? localStorage.getItem("last_tracking_number") : null;



  const payload = {
    cart: cartPayload,
    shipping: {
      trackingNumber: shippingTrackingNumber || null,
      address: {
        line1: address.line1 || "",
        city: address.city || "",
        state: address.state || "",
        zip: address.zip || "",
        phone: address.phone || "",
      },
      boxSize,
      shippingCost,
    },
  };

  console.log(payload);

  try {
    const res = await fetch("https://stripe-msb.makethemcall.workers.dev", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });

    const data = await res.json();
    const sessionUrl = data?.url;

    if (sessionUrl) {
      setCheckoutUrl(sessionUrl);
    } else {
      console.error("No Stripe URL returned.");
    }
  } catch (err) {
    console.error("Stripe error:", err);
  } finally {
    setPayNow(false);
  }
};



const loadCart = () => {
   

    


   const stored =  typeof window !== "undefined" ? localStorage.getItem("test_cart") : null;



  const items = stored ? JSON.parse(stored) : [];

  console.log(items);

  // Handle case where items only have IDs
  if (items.length && typeof items[0] === "string") {
    // fallback: cart was stored as list of IDs only
    // You need to fetch or reconstruct full product info here if available
    console.warn("Cart data is incomplete — contains only IDs.");
    return;
  }

  setCartIds(items.map((p) => p.id));
  setCartItems(items);
};


  const removeItem = (id) => {
    if(typeof window === "undefined" ) return 
    const updated = cartItems.filter((item) => item.id !== id);
    setCartItems(updated);
    setCartIds(updated.map((i) => i.id));
    localStorage.setItem("test_cart", JSON.stringify(updated));
  };

  React.useEffect(() => {
    loadCart();
  }, []);

const subtotal = cartItems.reduce((acc, item) => {
  const price = item?.sale_price ? parseFloat(item.sale_price) : parseFloat(item.regular_price || 0);
  return acc + price;
}, 0);


  const boxOptions = {
    small: { label: "Small (12×10×6)", length: 12, width: 10, height: 6 },
    medium: { label: "Medium (14×12×8)", length: 14, width: 12, height: 8 },
    large: { label: "Large (18×16×12)", length: 18, width: 16, height: 12 },
  };

  const calcShipping = async () => {
    const weight = cartItems.reduce((acc, item) => acc + parseFloat(item.weight || 0), 0);
    const box = boxOptions[boxSize];
    const dimWeight = (box.length * box.width * box.height) / 139;
    const finalWeight = Math.max(weight, dimWeight);

    const payload = {
      address: {
        streetLines: [address.line1 || ""],
        city: address.city || "",
        stateOrProvinceCode: address.state || "",
        postalCode: address.zip || "",
        countryCode: "US",
        residential: false,
      },
      pickupType: "DROPOFF_AT_FEDEX_LOCATION",
      rateRequestType: ["LIST"],
      weight: {
        units: "LB",
        value: finalWeight,
      },
      dimensions: {
        length: box.length,
        width: box.width,
        height: box.height,
        units: "IN",
      },
      serviceType: "FEDEX_GROUND",
    };
setShippingLoading(true);
try {
  const res = await fetch("https://fedex-msb.makethemcall.workers.dev/fedex-rate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  const data = await res.json();
  const detail = data?.output?.rateReplyDetails?.[0];
  const rated = detail?.ratedShipmentDetails?.[0];
  const shipmentDetail = rated?.shipmentRateDetail;
  const packageDetail = rated?.ratedPackages?.[0]?.packageRateDetail;

  const netCharge = rated?.totalNetCharge ?? packageDetail?.netCharge ?? 0;
  const billingWeight = shipmentDetail?.totalBillingWeight?.value ?? null;
  const actualWeight = payload.weight?.value ?? null;

  const dimWeightOverride = actualWeight && billingWeight && billingWeight > actualWeight;

  // Set values
  setShippingCost(parseFloat(netCharge || 0));
  setShippingMeta({
    weightUsed: billingWeight,
    dimOverride: dimWeightOverride,
    serviceType: detail?.serviceType || "Unknown",
    packagingType: detail?.packagingType || "Unknown"
  });

  console.log("FedEx shipping response parsed:", {
    serviceType: detail?.serviceType,
    packagingType: detail?.packagingType,
    finalCost: netCharge,
    finalWeight: billingWeight,
    usedDimWeight: dimWeightOverride
  });

} catch (err) {
  console.error("Shipping error:", err);
  setShippingCost(null);
  setShippingMeta(null);
} finally {
  setShippingLoading(false);
}


  };

  return (
    <GlobalProvider>
      <MainLayout>
                    <div style={{ width : '100%', height : 50 }}>  <button onClick={async () => {
                            navigate('/test');
                    }} style={{ background: "#0070f3", color: "#fff", padding: 10, border: "none", marginBottom: 6, cursor: "pointer", borderRadius: 4 }}>
                   BACK
                    </button> </div>
        <div style={{ display: "flex", padding: 20, gap: 20 }}>
          {/* LEFT: CART */}
          <div style={{ flex: 1 }}>
            <h3>🛒 Cart Items</h3>
            {cartItems.length === 0 ? (
              <p>No items in cart.</p>
            ) : (
              cartItems.map((item) => (
                <div key={item.id} style={{ marginBottom: 20, borderBottom: "1px solid #ccc", paddingBottom: 10 }}>
                  <h4>{item.name}</h4>
                  <p><strong>Price:</strong> ${item?.sale_price ? parseFloat(item.sale_price).toFixed(2) : parseFloat(item.regular_price || 0).toFixed(2)}</p>

                  <p><strong>Weight:</strong> {item.weight || "?"} lbs</p>
                  <p><strong>Dimensions:</strong> {item.dimensions?.length || "?"}×{item.dimensions?.width || "?"}×{item.dimensions?.height || "?"} in</p>
                  <button onClick={() => removeItem(item.id)} style={{ background: "crimson", color: "#fff", padding: "6px 10px", border: "none", cursor: "pointer" }}>
                    Remove
                  </button>
                </div>
              ))
            )}
          </div>

          {/* MIDDLE: ADDRESS + SHIPPING */}
          <div style={{ flex: 1 }}>
            <h3>Shipping Address</h3>
            {["line1", "line2", "city", "state", "zip", "phone"].map((field, i) => (
              <input key={i} type="text" placeholder={field.toUpperCase()} value={address[field] || ""} onChange={(e) => updateAddress(field, e.target.value)} style={{ width: "100%", marginBottom: 6 }} />
            ))}
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 10 }}>
              <button onClick={handlePrevAddress} disabled={addressIndex === 0}>◀ Prev</button>
              <button onClick={() => {
                  if(typeof window === "undefined" ) return 
                  const newAddresses = [...addresses, {}];
                  setAddresses(newAddresses);
                  setAddressIndex(newAddresses.length - 1);
                  localStorage.setItem("saved_addresses", JSON.stringify(newAddresses));
              }}>➕ Save New Address</button>
              <button onClick={handleNextAddress} disabled={addressIndex >= addresses.length - 1}>Next ▶</button>
            </div>
            <button onClick={async () => {
              const payload = {
                address: {
                  streetLines: [address.line1 || ""],
                  city: address.city || "",
                  stateOrProvinceCode: address.state || "",
                  postalCode: address.zip || "",
                  countryCode: "US",
                },
              };
              try {
                const res = await fetch("https://fedex-msb.makethemcall.workers.dev/fedex-validate", {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify(payload),
                });
                const data = await res.json();
                const matched = data?.output?.resolvedAddresses?.[0]?.attributes?.Matched;
                setValidStatus(matched === "true" ? true : matched === "false" ? false : "unknown");
              } catch {
                setValidStatus("unknown");
              }
            }} style={{ background: "#0070f3", color: "#fff", padding: 10, border: "none", marginBottom: 6, cursor: "pointer", borderRadius: 4 }}>
              Validate Address
            </button>
            <div style={{ fontWeight: "bold", marginBottom: 10, color: validStatus === "unknown" ? "#999" : validStatus === true ? "green" : "red" }}>
              Valid: {validStatus === "unknown" ? "unknown" : validStatus === true ? "true" : "false"}
            </div>
            <label>Box Size:</label>
            <select value={boxSize} onChange={(e) => setBoxSize(e.target.value)} style={{ width: "100%", marginBottom: 10 }}>
              {Object.entries(boxOptions).map(([key, opt]) => (
                <option key={key} value={key}>{opt.label}</option>
              ))}
            </select>
            <button onClick={calcShipping} disabled={shippingLoading} style={{ background: "#0070f3", color: "#fff", padding: 10, border: "none", cursor: "pointer", borderRadius: 4 }}>
              {shippingLoading ? "Calculating..." : "Calculate Shipping"}
            </button>
            <p style={{ marginTop: 10, fontStyle: "italic" }}>
              {shippingLoading ? "Please wait..." : shippingCost !== null ? `Shipping: $${shippingCost.toFixed(2)}` : "not yet"}
            </p>
          </div>

          {/* RIGHT: TOTAL */}
          <div style={{ flex: 1 }}>
            <h3>Totals</h3>
            <p><strong>Subtotal:</strong> ${subtotal.toFixed(2)}</p>
            <p><strong>Shipping:</strong> {shippingCost !== null ? `$${shippingCost.toFixed(2)}` : "—"}</p>
            <hr />
            <p><strong>Total:</strong> ${(subtotal + (shippingCost || 0)).toFixed(2)}</p>

            <button onClick={handleShipNow} disabled={shippingNow} style={{ marginTop: 10, background: "green", color: "#fff", padding: 10, border: "none", cursor: "pointer", borderRadius: 4 }}>
  {shippingNow ? "Shipping..." : "🚚 Ship Now"}
</button>
              
{shippingLabelUrl && (
  <div style={{ marginTop: 10 }}>
    <a href={shippingLabelUrl} target="_blank" rel="noopener noreferrer" style={{ color: "#0070f3", textDecoration: "underline" }}>
      📦 View Shipping Label
    </a>
  </div>
)}

<p>Must click Ship now before hitting Pay now in order to pass shipping id to payment function</p>


<br/><br/>
            <button onClick={handlePayNow} disabled={payingNow} style={{ marginTop: 10, background: "black", color: "#fff", padding: 10, border: "none", cursor: "pointer", borderRadius: 4 }}>
  {payingNow ? "Processing..." : "🚚 Pay Now"}
</button>





{checkoutUrl && (
  <div style={{ marginTop: 10 }}>
    <a href={checkoutUrl} target="_blank" rel="noopener noreferrer" style={{ color: "black", textDecoration: "underline" }}>
      💳 View Stripe Checkout
    </a>
  </div>
)}


          </div>
          
        </div>
      </MainLayout>
    </GlobalProvider>
  );
}
